import{_ as a,o as t,c as n,a5 as o}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Plan — FR 3.3.4: Update Client Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/02-profile/3-3-4-update-client-profile/plan.md","filePath":"feature/srs/02-profile/3-3-4-update-client-profile/plan.md"}'),i={name:"feature/srs/02-profile/3-3-4-update-client-profile/plan.md"};function l(s,e,r,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[o(`<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-3-4-update-client-profile" tabindex="-1">Plan — FR 3.3.4: Update Client Profile <a class="header-anchor" href="#plan-—-fr-3-3-4-update-client-profile" aria-label="Permalink to &quot;Plan — FR 3.3.4: Update Client Profile&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — tạo/sửa Client Profile của User đang đăng nhập. &gt; &gt; V2 (2026-10-02): <strong>[SỬA]</strong> Create/update không còn theo <code>agencyId</code> — xem <a href="./../3-3-3-view-client-profile/plan.html#6-lịch-sử-thay-đổi">3.3.3/plan.md §6</a>.</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code>, <code>brandhub-web</code></td></tr><tr><td>File implement</td><td><code>ClientProfileServiceImpl.createProfile()</code>, <code>updateById()</code>, <code>deleteById()</code></td></tr><tr><td>File liên quan</td><td><code>ClientProfileController</code> (<code>POST /api/v1/client-profile</code>, <code>PUT/DELETE /api/v1/client-profile/{profileId}</code>), <code>ClientProfileRequest</code></td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/client-profile</span></span>
<span class="line"><span>Authorization: Bearer &lt;access-token&gt;</span></span>
<span class="line"><span>Body: { displayName, company?, phone?, note?, logoUrl?, website?, industry?, location?, description?,</span></span>
<span class="line"><span>        socialLinks?, contactName?, contactEmail?, companySize?, instagramUrl?, taxCode?, address?,</span></span>
<span class="line"><span>        tagline?, foundedYear?, budgetRange? }</span></span>
<span class="line"><span>→ 201 ApiResponse&lt;ClientProfileResponse&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PUT /api/v1/client-profile/{profileId}</span></span>
<span class="line"><span>Body: &lt;same shape&gt;</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;ClientProfileResponse&gt;</span></span>
<span class="line"><span>→ 403 CLIENT_PROFILE_NOT_OWNED (profileId không thuộc caller)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DELETE /api/v1/client-profile/{profileId}</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;Void&gt;</span></span>
<span class="line"><span>→ 409 CLIENT_PROFILE_IN_USE (còn linked tới 1 workspace_members active)</span></span></code></pre></div><p>Không có <code>agencyId</code> ở bất kỳ request/response nào. Không có <code>email</code> — lấy từ <code>User</code> (authStore).</p><ul><li><strong>Không còn upsert theo (userId, agencyId)</strong> — create và update là 2 request riêng biệt, phân biệt bởi có/không có <code>profileId</code>.</li><li><strong>Full-overwrite</strong> vẫn giữ cho <code>PUT</code> — mỗi lần gửi đủ field, field thiếu bị ghi rỗng.</li></ul><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><p><code>client_profiles</code> — không có migration nào thêm <code>agency_id</code> nữa (đã bị huỷ bỏ và revert, xem <code>2026-10-02-drop-client-profile-agency-id.sql</code>). Field list đầy đủ: xem <a href="./../3-3-3-view-client-profile/plan.html#3-data-model">3.3.3/plan.md §3</a>.</p><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><p><strong>Create:</strong></p><ol><li>Build <code>ClientProfile.builder().userId(currentUser.getId())...</code> từ request.</li><li><code>save</code> → trả <code>ClientProfileResponse</code>.</li></ol><p><strong>Update:</strong></p><ol><li><code>findById(profileId)</code> → 404 nếu không có.</li><li>Check <code>profile.getUserId().equals(currentUser.getId())</code> → 403 <code>CLIENT_PROFILE_NOT_OWNED</code> nếu không khớp.</li><li>Ghi đè toàn bộ field từ request (full-overwrite), stamp <code>updatedAt</code>.</li><li><code>save</code> → trả <code>ClientProfileResponse</code>.</li></ol><p><strong>Delete:</strong></p><ol><li>Check ownership như update.</li><li>Check <code>workspaceMemberRepository.findByClientProfileIdInAndIsActiveTrue([profileId])</code> rỗng → nếu không rỗng, 409 <code>CLIENT_PROFILE_IN_USE</code>.</li><li><code>delete</code>.</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>View Client Profile</code> (3.3.3)</td></tr><tr><td>Bị chặn</td><td>—</td></tr></tbody></table><h2 id="tich-hop-frontend-web-mobile-đa-trien-khai" tabindex="-1">Tích hợp Frontend Web &amp; Mobile (Đã triển khai) <a class="header-anchor" href="#tich-hop-frontend-web-mobile-đa-trien-khai" aria-label="Permalink to &quot;Tích hợp Frontend Web &amp; Mobile (Đã triển khai)&quot;">​</a></h2><ul><li><strong>Web (<code>brandhub-web</code>):</strong> <code>src/pages/workspace/client-profile.tsx</code>, <code>src/services/clientProfileService.ts</code> — đồng bộ song song locale <code>vi</code>/<code>en</code> (<code>clientProfile.*</code>) và semantic Light/Dark mode tokens.</li><li><strong>Mobile (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/ClientProfileScreen.tsx</code>, <code>src/services/clientProfileService.ts</code> — đồng bộ API contract, token state và kiểm tra lỗi nhất quán với Web.</li><li><strong>Tài liệu tham chiếu:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Authentication &amp; Profile</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>`,22)])])}const f=a(i,[["render",l]]);export{u as __pageData,f as default};
